(function () {
  var FAQS = [
    { q: "What DAW do I need? Will this work in mine?",
      a: "<p>The MIDI files work in <strong>every major DAW</strong> — FL Studio, Ableton Live, Logic Pro, Studio One, Cubase, Pro Tools, GarageBand, Reaper, Bitwig. MIDI is a universal format. Just drag and drop the file into a track and load your own piano, synth, or pad on top.</p>" },
    { q: "Wait — is this samples or MIDI?",
      a: "<p>This is <strong>pure MIDI</strong>. You get the chord progressions — every chord, voicing, and inversion — exactly as they appear in the original songs, with each file labelled by <strong>key and BPM</strong>.</p><p>Why MIDI matters: with MIDI you can use <strong>any instrument you want</strong>, change the key with one click, swap sounds, edit individual notes. Samples lock you in. MIDI sets you free.</p>" },
    { q: "How do I find the right progression fast out of 1,000?",
      a: "<p>Every file is named with the <strong>artist, song, key and BPM</strong>, and the whole pack is organised by artist. So if you want a moody minor progression at 120 BPM, or the exact chords behind a specific hit, you can find it in seconds — then drag the MIDI in and transpose it to your track's key.</p>" },
    { q: "Are these the actual song MIDIs?",
      a: "<p>No — these are <strong>painstakingly transcribed</strong> by ear, note for note. Every chord, voicing, and passing change has been transcribed from the original recordings. They sound identical to the originals when played through similar instruments, but they're original recreations, not extracted from the master tracks.</p>" },
    { q: "Can I sell beats made with these MIDI files?",
      a: "<p><strong>Yes.</strong> You get a full commercial license. Use the MIDI files in beats you sell on BeatStars, Airbit, Traktrain, or directly to artists. Use them in songs you release on Spotify, Apple Music, or anywhere else. Profit is yours to keep.</p><p>The only thing you can't do is resell or redistribute the MIDI files themselves as a pack.</p>" },
    { q: "How fast do I get access?",
      a: "<p><strong>Instantly.</strong> The second your payment goes through, you'll get an email with your download link. No waiting, no shipping, no setup. You can be making beats with the pack within 5 minutes.</p>" },
    { q: "Do I need to know music theory?",
      a: "<p>Not at all. That's the whole point. The MIDI files <em>are</em> the theory — the chords, the voicings, the movement. Drop them in and you're already starting from a hit-level harmonic foundation. Add your own sound, your own melody, your own drums on top.</p>" },
    { q: "What if I don't like it?",
      a: "<p>If the pack isn't what you expected, just reply to your order email within <strong>14 days</strong> and we'll refund you in full. No forms, no questions, no hassle.</p>" },
    { q: "What devices does this work on?",
      a: "<p>Anywhere you can run a DAW — <strong>Mac, Windows, Linux</strong>, even iPad and iPhone if you produce in mobile DAWs like BeatMaker 3, GarageBand iOS, or Cubasis.</p>" },
    { q: "Will I get future updates or new packs?",
      a: "<p>Yes — when we release new MIDI packs, existing owners get them at a steep discount or free, depending on the drop. We'll email you whenever a new volume goes live.</p>" },
    { q: "How is this different from free YouTube tutorials?",
      a: "<p>YouTube shows you <em>one progression</em> in 12 minutes of fluff. This pack hands you <strong>1,000 progressions</strong> from real hits in one folder, each labelled with key and BPM so you can find the right one in seconds. No talking, no ads, no missing details.</p><p>One chord transcription on Fiverr costs €20+. You're getting 1,000 of them for €27.</p>" }
  ];

  function build() {
    // Find or create mount
    var mount = document.getElementById('fbFaqMount');
    if (!mount) {
      mount = document.createElement('div');
      mount.id = 'fbFaqMount';
      var sc = document.currentScript || (function(){ var s = document.getElementsByTagName('script'); return s[s.length-1]; })();
      if (sc && sc.parentNode) sc.parentNode.insertBefore(mount, sc);
      else document.body.appendChild(mount);
    }

    // Inject styles once
    if (!document.getElementById('fbFaqStyles')) {
      var fontLink = document.createElement('link');
      fontLink.rel = 'stylesheet';
      fontLink.href = 'https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;700;800&display=swap';
      document.head.appendChild(fontLink);

      var style = document.createElement('style');
      style.id = 'fbFaqStyles';
      style.innerHTML =
        ".fb-faq{--fb-ink:#0a0a0a;--fb-ink-soft:#2a2a2a;--fb-line:#e6e6e8;--fb-card:#fff;--fb-accent:#7c3aed;box-sizing:border-box;width:100%;max-width:820px;margin:0 auto;padding:20px 0;color:#0a0a0a;font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased;line-height:1.5}" +
        ".fb-faq *,.fb-faq *::before,.fb-faq *::after{box-sizing:border-box}" +
        ".fb-faq button{font-family:inherit}" +
        ".fb-faq-eyebrow{text-align:center;color:#7c3aed;font-size:12px;font-weight:800;letter-spacing:0.22em;text-transform:uppercase;margin:0 0 10px}" +
        ".fb-faq-title{font-family:'Anton','Bebas Neue',Impact,sans-serif;font-weight:400;font-size:clamp(36px,7vw,60px);line-height:0.95;letter-spacing:0.005em;margin:0 0 12px;text-align:center;text-transform:uppercase;color:#fff}" +
        ".fb-faq-title em{font-style:normal;color:#a855f7;position:relative;display:inline-block}" +
        ".fb-faq-title em::after{content:'';position:absolute;left:0;right:0;bottom:4%;height:6px;background:#a855f7;opacity:0.18;z-index:-1}" +
        ".fb-faq-subtitle{text-align:center;color:rgba(255,255,255,0.7);font-size:clamp(15px,2vw,17px);margin:0 auto 32px;max-width:520px}" +
        ".fb-faq-list{display:flex !important;flex-direction:column !important;gap:12px;width:100% !important}" +
        ".fb-faq-item{background:#fff;border:2px solid #0a0a0a;border-radius:8px;box-shadow:3px 3px 0 #0a0a0a;overflow:hidden;transition:box-shadow 0.15s,border-color 0.15s;width:100% !important;display:block !important}" +
        ".fb-faq-item.is-open{border-color:#7c3aed;box-shadow:3px 3px 0 #7c3aed}" +
        ".fb-faq-trigger{width:100%;display:flex !important;align-items:center;justify-content:space-between;gap:16px;padding:18px 22px;background:transparent;border:none;cursor:pointer;text-align:left !important;font-size:16px;font-weight:700;color:#0a0a0a;line-height:1.35;transition:background 0.15s;font-family:inherit}" +
        ".fb-faq-trigger:hover{background:rgba(124,58,237,0.05)}" +
        ".fb-faq-trigger:focus{outline:none;background:rgba(124,58,237,0.05)}" +
        ".fb-faq-icon{flex-shrink:0;width:28px;height:28px;border-radius:50%;background:#0a0a0a;color:#fff;position:relative;transition:background 0.2s,transform 0.25s ease;display:inline-block}" +
        ".fb-faq-icon::before,.fb-faq-icon::after{content:'';position:absolute;top:50%;left:50%;background:#fff;border-radius:1px;transition:transform 0.25s ease}" +
        ".fb-faq-icon::before{width:12px;height:2px;transform:translate(-50%,-50%)}" +
        ".fb-faq-icon::after{width:2px;height:12px;transform:translate(-50%,-50%)}" +
        ".fb-faq-item.is-open .fb-faq-icon{background:#7c3aed;transform:rotate(180deg)}" +
        ".fb-faq-item.is-open .fb-faq-icon::after{transform:translate(-50%,-50%) scaleY(0)}" +
        ".fb-faq-panel{overflow:hidden;height:0;transition:height 0.28s ease}" +
        ".fb-faq-panel-inner{padding:18px 22px 22px;color:#2a2a2a;font-size:15.5px;line-height:1.6;border-top:1px solid #e6e6e8}" +
        ".fb-faq-panel-inner p{margin:0 0 12px}" +
        ".fb-faq-panel-inner p:last-child{margin-bottom:0}" +
        ".fb-faq-panel-inner strong{color:#0a0a0a;font-weight:700}" +
        ".fb-faq-cta{text-align:center;margin-top:36px;padding:24px 20px;border:2px dashed rgba(255,255,255,0.4);background:rgba(0,0,0,0.2);border-radius:8px}" +
        ".fb-faq-cta-text{color:rgba(255,255,255,0.85);margin:0 0 6px;font-size:15px;font-weight:500}" +
        ".fb-faq-cta-link{display:inline-block;color:#a855f7;text-decoration:none;font-weight:800;font-size:17px;letter-spacing:0.01em;border-bottom:2px solid transparent;transition:border-color 0.15s}" +
        ".fb-faq-cta-link:hover{border-bottom-color:#a855f7}" +
        "@media (max-width:540px){.fb-faq{padding:16px 0}.fb-faq-subtitle{padding:0 12px;margin-bottom:24px}.fb-faq-trigger{padding:16px 18px;font-size:15px;gap:12px}.fb-faq-icon{width:26px;height:26px}.fb-faq-panel-inner{padding:16px 18px 18px;font-size:14.5px}.fb-faq-cta{margin-top:28px;padding:20px 16px}}";
      document.head.appendChild(style);
    }

    function escapeHtml(s) {
      return String(s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
      });
    }

    var itemsHtml = '';
    for (var i = 0; i < FAQS.length; i++) {
      itemsHtml += '<div class="fb-faq-item">' +
        '<button type="button" class="fb-faq-trigger" aria-expanded="false">' +
          '<span>' + escapeHtml(FAQS[i].q) + '</span>' +
          '<span class="fb-faq-icon" aria-hidden="true"></span>' +
        '</button>' +
        '<div class="fb-faq-panel">' +
          '<div class="fb-faq-panel-inner">' + FAQS[i].a + '</div>' +
        '</div>' +
      '</div>';
    }

    mount.innerHTML =
      '<div class="fb-faq">' +
        '<p class="fb-faq-eyebrow">FREQUENTLY ASKED</p>' +
        '<h2 class="fb-faq-title">GOT <em>QUESTIONS?</em></h2>' +
        '<p class="fb-faq-subtitle">Everything you need to know before grabbing the pack.</p>' +
        '<div class="fb-faq-list">' + itemsHtml + '</div>' +
      '</div>';

    var list = mount.querySelector('.fb-faq-list');
    list.addEventListener('click', function (e) {
      var t = e.target;
      while (t && t !== list && (!t.className || String(t.className).indexOf('fb-faq-trigger') === -1)) {
        t = t.parentNode;
      }
      if (!t || t === list) return;
      var item = t.parentNode;
      var panel = item.querySelector('.fb-faq-panel');
      var isOpen = String(item.className).indexOf('is-open') !== -1;

      var openItems = list.querySelectorAll('.fb-faq-item.is-open');
      for (var j = 0; j < openItems.length; j++) {
        if (openItems[j] === item) continue;
        openItems[j].className = 'fb-faq-item';
        openItems[j].querySelector('.fb-faq-trigger').setAttribute('aria-expanded', 'false');
        openItems[j].querySelector('.fb-faq-panel').style.height = '0px';
      }

      if (isOpen) {
        panel.style.height = panel.scrollHeight + 'px';
        setTimeout(function(){ panel.style.height = '0px'; }, 10);
        item.className = 'fb-faq-item';
        t.setAttribute('aria-expanded', 'false');
      } else {
        panel.style.height = panel.scrollHeight + 'px';
        item.className = 'fb-faq-item is-open';
        t.setAttribute('aria-expanded', 'true');
        setTimeout(function(){
          if (String(item.className).indexOf('is-open') !== -1) panel.style.height = 'auto';
        }, 320);
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else {
    build();
  }
})();
